    description: "银杏为落叶大乔木，高可达 40 m，树干通直，树皮灰褐色并纵裂，老树枝条分为长枝与短枝两种。叶片呈折扇状，具二叉状叶脉，是裸子植物中罕见的宽阔叶形；入秋叶色转为金黄，观赏价值极高。雌雄异株，雄球花呈葇荑状下垂，雌球花具长柄，种子成熟时外种皮橙黄肉质并散发异味，内种皮洁白坚硬。\n\n银杏原产中国，野生种群仅零星分布于浙江天目山、湖北大洪山等地，但作为行道树与园林树遍植南北各地，耐寒、耐旱、抗烟尘，寿命可达千年以上。木材纹理细密，可供雕刻与制作家具；种仁即白果，可煮食或入药，但含微量银杏毒素，须熟食且不宜过量；叶片提取物也被用于制药。银杏生长缓慢，俗称“公孙树”，意即公公栽树、孙辈才能收果；许多寺庙与古村落至今仍保存着树龄数百年乃至上千年的银杏古树。",
