    description: "水杉为落叶乔木，高可达 35 m，主干通直，树皮红褐色并呈条片状剥落；小枝对生，叶片条形、扁平而柔软，在侧枝上排成羽状两列，入秋转为红褐色，随后连同小枝一同脱落。雌雄同株，球花单性，球果近球形，成熟时深褐色，种子扁平并具翅，可随风传播。\n\n水杉曾被认为早已灭绝，1941 年植物学家在湖北利川谋道溪发现活体植株，轰动世界植物学界。野生种群仅分布于湖北利川、重庆石柱与湖南龙山交界的狭窄山区，喜温暖湿润气候与排水良好的酸性土壤。水杉生长迅速，20 年即可成材，耐水湿，常用于河岸护堤与湿地绿化，现已引种到世界各地。水杉的重新发现被视为 20 世纪植物学最重要的成就之一，如今长江流域的湿地与公园中随处可见成片的水杉林。",
