    description: "珙桐为落叶乔木，高可达 20 m，树皮深灰褐色并呈块状开裂；叶片宽卵形，边缘具粗锯齿，基出脉明显。花序为头状花序，由一朵两性花与多朵雄花组成，花序基部生有两枚大形白色苞片，长可达 15 cm，形似鸽翼，随风摇曳时宛若群鸽栖枝，因而得名“鸽子树”。核果青紫色，内含坚硬种子。\n\n珙桐是第三纪古热带植物的孑遗种，野生种群仅见于湖北、湖南、四川、贵州、云南等地的中山常绿阔叶林与落叶阔叶混交林，喜凉爽湿润气候与肥沃排水良好的土壤。它的白色苞片并非花瓣，而是特化的叶，用以吸引传粉昆虫。木材可制家具，树形优美，是世界著名的观赏树种，已被广泛引种栽培。每年 4 月前后，珙桐的白色苞片如群鸽展翅，随风轻摇，吸引众多游人与研究者前来观赏，是春季最引人注目的珍稀花木。",
