    description: "香樟为常绿大乔木，高可达 30 m，树冠广卵形，树皮灰褐色并呈不规则纵裂；单叶互生，卵形或椭圆形，薄革质，揉碎后有浓烈的樟脑香气；春季新叶嫩绿泛红，老叶背面常带白粉。圆锥花序腋生，花小、黄绿色，不甚显著；浆果近球形，成熟时紫黑色，基部具宿存花萼。\n\n香樟原产中国南方及东南亚，喜温暖湿润与深厚肥沃的酸性土壤，在长江流域以南的平原、丘陵与村旁广泛分布，常作为庭院树、行道树与风景林树种。根、枝、叶富含樟脑与樟油，可提取用于医药、香料与防虫；木材致密、耐腐防虫，是制作箱柜、雕刻与乐器的上等材料。由于野生古树资源减少，香樟被列为国家二级保护野生植物。杭州、苏州等江南城市常以香樟为市树或主要行道树，初夏花开时满城清香，也是当地人共同的季节记忆。",
