    description: "国槐为落叶乔木，高可达 25 m，树冠圆球形，树皮灰褐色并具块状裂纹；奇数羽状复叶，小叶 7–17 枚，卵状长圆形，表面深绿。夏季开花，圆锥花序顶生，花冠蝶形、淡黄白色，雄蕊 10 枚离生；荚果呈念珠状，成熟时不开裂，冬季仍悬挂枝头。\n\n国槐原产中国，栽培历史逾两千年，北方城乡常见，耐寒、耐旱、耐轻度盐碱，对土壤要求不严。未开放的花蕾经蒸煮干燥后即为中药“槐米”，可凉血止血；花可作黄色染料；木材坚硬，可制家具与农具；树形端正、遮荫效果好，是优良的行道树。民间有“门前一棵槐，不是招宝就是进财”的俗语。国槐与常见的刺槐容易混淆，前者小叶先端尖、荚果呈念珠状，后者枝条具托叶刺、荚果扁平；槐木耐腐，古代还常用于制作车辕与建筑构件。",
