    description: "梧桐为落叶乔木，高可达 16 m，树干挺直，树皮青绿色、平滑；叶片掌状 3–5 裂，直径可达 30 cm，裂片全缘，叶柄与叶片近等长。圆锥花序顶生，花单性同株，淡黄绿色；蓇葖果成熟前开裂呈叶状，种子圆球形，着生于果瓣边缘，形如小舟上的圆珠，故有“青桐”“碧梧”之称。\n\n梧桐原产中国，栽培历史悠久，华北以南各地常见，喜光、喜深厚湿润土壤，生长迅速。木材轻软，可制乐器、箱匣；树皮纤维可造纸；种子可榨油，炒食不宜过量。古人以梧桐引凤、一叶知秋，古琴面板多用梧桐木制作，故琴又称“丝桐”，梧桐因此成为传统文化中的祥瑞之树。梧桐生长较快，幼苗期需注意防寒，成年树萌蘖能力强，被砍伐后能从根部萌发新枝；江南园林中常将梧桐与芭蕉、竹、太湖石搭配，构成经典庭院景致。",
