    description: "毛白杨为落叶大乔木，高可达 30 m，树干通直，树冠卵圆形；树皮灰绿色，老树基部纵裂；长枝上的叶片三角状卵形、较大，短枝上的叶片较小、卵圆形，叶背及叶柄密被白色绒毛，故得名。早春先花后叶，雄花序呈葇荑状下垂，雌花序较细长；蒴果成熟后裂开，吐出白色杨絮。\n\n毛白杨是中国特有树种，分布于华北、西北至黄淮海平原，喜光、耐寒、耐旱，对土壤适应性强，生长快，是北方平原绿化的主力。木材轻软，可供建筑、家具、造纸与火柴用；树皮可入药，有祛风除湿之效。作为“三北”防护林与农田林网的主要树种，毛白杨在防风固沙、保护农田方面作用显著，但春季杨絮也给部分城市带来困扰。毛白杨根蘖能力强，采伐后容易萌发新枝；叶片在风中哗哗作响，是北方平原上让人熟悉的声音。",
