    description: "雪松为常绿针叶乔木，高可达 50 m，树冠塔形，主干挺拔，大枝平展、小枝略下垂，树姿庄严；树皮灰褐色、呈鳞状开裂。叶片针形、坚硬，长 2.5–5 cm，在短枝上簇生、长枝上螺旋状散生，灰绿色或银灰色。雌雄同株，雄球花圆柱形、黄色，雌球花卵圆形、紫红色；球果椭圆状卵形，长 7–12 cm，成熟时红褐色，种子具翅。\n\n雪松原产喜马拉雅山西部海拔 1200–3300 m 的山地，中国西藏、印度、尼泊尔、阿富汗有天然分布，长江流域及华北各地广泛栽培。它喜光、耐寒，适宜深厚排水良好的土壤，在暖湿地区生长迅速、树形优美，是世界著名的观赏树种，与金钱松、日本金松并称“世界三大庭园树”。木材纹理通直、耐腐，可供建筑与家具；枝叶可提取精油，常作为公园、校园与庭院的景观树。",
