    description: "楠木为常绿大乔木，高可达 30 m，胸径可达 1.5 m，树干通直，树皮灰褐色、纵裂；小枝与顶芽密被黄褐色柔毛。叶片革质，椭圆形至披针形，上面深绿光亮，下面密被短柔毛，叶脉明显。花序为圆锥花序，生于新枝上部，花小、黄绿色；果实为浆果状核果，椭圆形，成熟时黑色，基部具宿存花被。\n\n楠木是中国特有树种，野生分布于四川、贵州、湖北、湖南等地海拔 1000–1500 m 的常绿阔叶林中，喜温暖湿润、耐阴，适宜深厚肥沃的酸性土壤。木材淡黄褐色，纹理细腻、香气独特，耐腐防虫，不易变形，是建筑、家具、雕刻与棺木的上等材料；明清皇家宫殿大量使用楠木，故有“金丝楠木”之称。由于长期过度采伐，楠木野生资源濒临枯竭，被列为国家二级保护野生植物。",
