    summary: "中国南方海岸红树林的代表树种，树干基部生有拱形支柱根，果实成熟后直接在母树上发芽，形成“胎生苗”。",
    description: "秋茄为常绿灌木或小乔木，高可达 8 m，树皮灰褐色；最显著的特征是树干基部长出密集的拱形支柱根，扎入滩涂淤泥中固着植株。叶片对生，革质，椭圆形，长 5–10 cm，上面深绿、下面淡绿。花序为聚伞花序，生于叶腋，花白色、5 裂；果实长圆锥形，成熟后不脱落，种子在母树上发芽长出胚轴，形成细长的“胎生苗”，落入淤泥后即可扎根。\n\n秋茄分布于中国广东、广西、福建、海南、浙江及日本、东南亚的海岸潮间带，是红树林的主要组成树种，耐盐、耐淹，每天被潮水浸没仍能正常生长。密集的支柱根与胎生繁殖是适应潮间带环境的典型特征；红树林能防风消浪、护岸固滩，为鱼虾蟹与鸟类提供栖息地，被称为“海岸卫士”。树皮可提取鞣料，木材可制小器具，全株具有重要的生态价值。",
