    description: "玉兰为落叶乔木，高可达 15 m，树冠卵圆形，树皮灰白色而光滑；枝条粗壮，顶芽密被灰白色长毛。叶片倒卵形或宽倒卵形，先端突尖，全缘。花期 2–3 月，先花后叶，花朵单生于枝顶，直径 10–15 cm，花被片 9 枚、白色，基部常带淡粉，形似玉盏，芳香宜人；聚合蓇葖果圆柱形，成熟时裂开，露出红色种子。\n\n玉兰原产中国中部及长江流域，栽培历史逾两千年，喜光、稍耐阴，耐寒，适宜深厚肥沃、排水良好的微酸性土壤。因其花大、色白、香雅，常被种植于庭院、寺庙与园林中，与海棠、迎春、牡丹并称“玉堂春富贵”。花蕾可入药，中药称“辛夷”，能散风寒、通鼻窍；花瓣可裹面油炸食用；木材可供细木工用，是中国多数城市的早春标志性观赏树。",
