    summary: "中国西北荒漠河岸的珍稀落叶乔木，耐旱、耐盐碱，叶片有三种形状，被称为“沙漠英雄树”，有“生而千年不死”之说。",
    description: "胡杨为落叶乔木，高可达 15 m，树皮灰褐色、纵裂，老树干常扭曲；叶片形状多变，幼树与萌条上的叶为披针形，成年树上的叶为卵圆形或肾形，同一棵树上可见多种叶形，故又称“异叶杨”。雌雄异株，葇荑花序下垂，花期 4–5 月；蒴果长椭圆形，成熟后裂开，种子带白色绒毛，可随风传播。\n\n胡杨分布于中亚、蒙古及中国新疆塔里木河、内蒙古额济纳等地，是荒漠河岸林的主要树种，耐干旱、耐盐碱、耐风沙，靠发达的根系吸收地下水，可在含盐量较高的土壤中生长。胡杨林是荒漠地区重要的生态屏障，为野生动物提供栖息地，也能防风固沙；木材可供建筑，树液可提取胡杨碱。民间有“生而千年不死，死而千年不倒，倒而千年不朽”的说法，胡杨因此成为坚韧精神的象征。",
