    description: "蓝花楹为落叶乔木，高可达 15 m，树冠开展，树皮灰褐色；叶片为二回羽状复叶，小叶细小，呈蕨类状，排列轻盈。花期春末夏初，圆锥花序顶生，花冠钟形、蓝紫色，长 4–5 cm，成片开放时满树蓝紫，落花铺满地面如紫色地毯。果实为木质蒴果，扁平圆形，成熟时褐色并开裂，种子带薄翅，可随风传播。\n\n蓝花楹原产南美洲巴西、阿根廷、玻利维亚等地，喜温暖湿润、光照充足的环境，不耐寒，适宜深厚肥沃、排水良好的沙壤土。因其花色独特、花期集中，被广泛引种到澳大利亚、南非及中国南方城市作为行道树与庭园树，花期常成为当地重要的旅游景观；澳大利亚布里斯班、南非比勒陀利亚均以蓝花楹闻名。木材轻软，可用于家具与工艺品，树形优美，是园林中的名贵观花树种。",
