    description: "华山松为常绿针叶乔木，高可达 35 m，树皮灰绿色、平滑，老树呈块片状开裂；针叶 5 针一束，长 8–15 cm，细软下垂，叶鞘早落。雌雄同株，雄球花黄色、簇生于新枝下部，雌球花紫红色、生于枝顶；球果圆锥状长卵形，长 10–20 cm，成熟时黄褐色，鳞片开裂散出无翅种子。\n\n华山松分布于中国陕西、山西、甘肃、四川、云南、贵州、湖北等地的中高山地带，是华山、秦岭等地的标志性松树之一，喜光、耐寒，适宜深厚肥沃、排水良好的山地棕壤，常与栎类、桦木构成混交林。木材轻软、纹理通直，可供建筑、家具与造纸；种子即松子，可炒食与榨油；树皮可提取栲胶。华山松也是荒山造林与水土保持的重要树种，在园林中常作景观树栽培。",
