    description: "枫香为落叶乔木，高可达 40 m，树干通直，树皮灰褐色、方块状剥落；叶片掌状 3 裂，稀 5 裂，边缘具锯齿，幼叶常带红色。花期 3–4 月，花单性同株，雄花序为葇荑花序，雌花序为头状花序；果实为球形聚合果，由多数蒴果组成，具刺状宿存花柱，成熟时开裂散出带翅种子，果序俗称“路路通”。\n\n枫香分布于中国长江流域以南及华东、华中、西南地区，喜光、喜温暖湿润，耐干旱瘠薄，适宜酸性或中性土壤，是南方低山丘陵常见的落叶阔叶树种。秋季叶色转为鲜红或橙红，是重要的秋色叶观赏树；树脂即枫香脂，可入药，有活血止痛之效；果序“路路通”也是中药；木材可供建筑与家具用。枫香与槭树类常被统称为“枫”，但前者果实为球形蒴果序，后者为双翅果。",
