    description: "悬铃木为落叶大乔木，高可达 30 m，树冠宽阔；树皮灰绿色或灰白色，呈不规则片状剥落，剥落后露出浅色内皮，形成斑驳花纹。叶片宽卵形，掌状 5–7 裂，裂片边缘具粗齿，叶柄长。花单性同株，头状花序球形；果实为球形聚合果，通常 2 个生于一总柄上，故称“二球悬铃木”，果序悬挂枝头越冬，成熟后散出带毛种子。\n\n悬铃木是杂交种，由原产北美的北美悬铃木（一球悬铃木）与原产欧亚的三球悬铃木杂交而成，适应性广，耐寒、耐修剪，对城市烟尘与有害气体抗性强。中国各地广泛栽培作行道树与庭园树，上海、南京等城市的老街道上常见高大的悬铃木。木材可供家具与细木工用；树皮与叶可入药。因其叶似梧桐、又由法国人引入，民间常称“法国梧桐”，但它与真正的梧桐、泡桐都不是同一种植物。",
