    description: "槲树为落叶乔木，高可达 25 m，树皮暗灰褐色、纵裂；叶片宽倒卵形至倒卵状楔形，长 10–30 cm，边缘具 4–10 对波状圆齿，叶背密被灰黄色星状绒毛，叶柄极短。雌雄同株，雄花序为下垂葇荑花序，雌花单生或簇生；壳斗杯形，苞片狭披针形、反曲，坚果卵圆形，长 1.5–2.5 cm。\n\n槲树分布于中国东北、华北至西南及朝鲜半岛、日本，喜光、耐寒、耐旱，适应性强，常生于山坡、丘陵与林缘，是北方落叶阔叶林的重要组成树种。木材坚硬，可供建筑、家具与薪炭用；叶可饲养柞蚕；树皮与壳斗含单宁，可提取栲胶；坚果可酿酒或作饲料。槲树叶片硕大、秋色黄褐，也是山地景观树种，在朝鲜半岛与日本文化中常被视为乡野生活的象征。",
