    description: "黄葛树为落叶大乔木，高可达 25 m，树冠庞大，树皮灰褐色；枝条上生有气生根，垂落后可形成支柱根；叶片互生，纸质，卵状披针形或椭圆形，先端渐尖，叶柄细长。花期 4–5 月，隐头花序生于叶腋，榕果球形，成熟时黄绿色或橙红色，内含多数细小瘦果，是鸟类与昆虫的食物。\n\n黄葛树分布于中国西南、华南及东南亚地区，喜温暖湿润、光照充足，耐旱、耐瘠薄，在江边、崖壁与石缝中也能生长。它发叶晚、落叶早，春季新叶萌发时老叶脱落，常在同一时期呈现落叶与新叶交替的景观；气生根盘结于岩石与墙体，形成“树抱石”的独特景观。树冠遮荫面积大，是西南地区重要的庭荫树与行道树；树皮纤维可制绳，根与叶可入药。黄葛树是重庆的市树之一，在当地具有重要的文化意义。",
