    description: "臭椿为落叶乔木，高可达 20 m，树皮灰褐色、平滑或纵裂；奇数羽状复叶，小叶 13–25 枚，卵状披针形，基部具 1–2 对粗齿，齿端有腺体，揉碎后散发异味。花期 5–6 月，圆锥花序顶生，花小、黄绿色；果实为翅果，长圆形，成熟时浅黄褐色或红褐色，成串挂在枝头，可宿存至冬季。\n\n臭椿原产中国北部、中部及东亚地区，中国各地常见，喜光、耐寒、耐旱、耐瘠薄，对二氧化硫等有害气体抗性强，生长迅速，是荒山造林与工业区绿化的先锋树种。木材轻软、易于加工，可供家具、农具与造纸用；树皮、根皮与果实可入药，中药“椿根皮”“凤眼草”有清热燥湿之效；叶可饲养樗蚕。臭椿在欧美被引种后因繁殖力强而成为入侵树种，需要加以管理。",
