    description: "楝树为落叶乔木，高可达 20 m，树皮暗灰褐色、纵裂；二至三回羽状复叶，小叶卵形至椭圆形，边缘具锯齿。花期 4–5 月，圆锥花序腋生，花淡紫色、芳香，花瓣 5 枚，雄蕊合生成紫色筒状；核果椭圆形或球形，成熟时黄褐色，冬季仍挂于枝头，内含 4–5 粒种子。\n\n楝树分布于中国黄河以南至华南、西南各地，也见于印度、东南亚，喜光、喜温暖湿润，耐干旱瘠薄，适应性强，常生于村旁、路旁与河边。木材轻软、纹理直，可供家具、农具与乐器用；树皮纤维可制绳、造纸；根皮、树皮与果实可入药，能驱虫、止痛，但果实有毒，不可食用。楝树也是传统的生物农药来源，其提取物可用于防治农业害虫，树形优美、花香淡雅，是优良的庭荫树。",
