    description: "槟榔为常绿乔木，高可达 20 m，树干通直、不分枝，表面有环状叶痕；羽状复叶长 1.5–2 m，小叶多数、线状披针形，先端不规则齿裂，叶鞘绿色。花期 3–5 月，肉穗花序生于叶鞘下方，雌雄同序；核果卵圆形或长圆形，长 3–5 cm，成熟时橙红色或黄褐色，内含 1 粒种子，即“槟榔子”。\n\n槟榔原产马来西亚、印度尼西亚一带，中国海南、台湾、云南等地栽培，喜高温多湿、光照充足，适宜深厚肥沃、排水良好的热带土壤。果实是东南亚与南亚地区传统的咀嚼品，常与蒌叶、石灰一起嚼食，也是重要的中药材，种子含槟榔碱，有驱虫作用；树干可作建筑材料，叶可编席与制扇。需要提醒的是，长期嚼食槟榔与口腔癌风险相关，世界卫生组织已将其列为致癌物，应避免长期嚼食。",
