    description: "油棕为常绿乔木，高可达 10 m，树干粗壮、不分枝，表面有环状叶痕；羽状复叶长可达 7 m，小叶多数、线状披针形，叶柄基部具刺。花期全年，肉穗花序生于叶腋，雌雄同株异序；果实为聚花果，由数百个卵形核果组成，果皮橙红色、富含油脂，果肉可榨棕榈油，果仁可榨棕榈仁油。\n\n油棕原产西非热带地区，马来西亚、印度尼西亚、尼日利亚等国广泛栽培，中国海南、云南、广东等地有引种。它喜高温多湿、光照充足，适宜深厚肥沃、排水良好的热带土壤，定植后 3–4 年开始结果，经济寿命约 20–25 年。单位面积产油量远高于大豆、油菜等油料作物，棕榈油广泛用于食品、肥皂与生物柴油；但油棕种植扩张也带来雨林砍伐等生态问题，可持续棕榈油认证因此受到关注。",
