    description: "鹅掌楸为落叶乔木，高可达 40 m，树皮灰白色、纵裂；叶片互生，形似马褂或鹅掌，先端平截或微凹，两侧各具 1–2 个裂片，叶柄长。花期 4–5 月，花单生于枝顶，花冠杯状，花被片 9 枚、外轮绿色、内轮黄绿色并带橙色条纹，形似郁金香；聚合翅果纺锤形，成熟时散出带翅种子。\n\n鹅掌楸是中国特有树种，分布于长江流域以南及华东、华中、西南的山地，喜光、喜温暖湿润，适宜深厚肥沃、排水良好的酸性土壤。木材纹理直、易加工，可供建筑、家具与细木工用；树形端正、叶形奇特、花似郁金香，是世界著名的观赏树种；树皮可入药。由于野生资源稀少、天然更新困难，鹅掌楸被列为国家二级保护野生植物，各地已开展人工繁育与引种栽培。",
