    description: "相思树为常绿乔木，高可达 15 m，树皮灰褐色；叶片退化，叶柄膨大成披针形的叶状柄，长 5–10 cm，形似叶片，是长期适应干旱环境的结果。花期 4–6 月，头状花序腋生，花小、黄色，由多数小花聚成小球；荚果扁平、线形，成熟时褐色，内含多数种子。\n\n相思树分布于中国台湾、福建、广东、广西、海南等地及东南亚，喜光、耐旱、耐瘠薄，适应性强，是南方丘陵与滨海地区的常见树种。木材坚硬，可供家具与薪炭用；树皮可提取栲胶；根系发达、能固氮，是荒山绿化与水土保持的优良树种。相思树在台湾被称为“相思仔”，是台湾最具代表性的乡土树种之一，因木材可制“相思木炭”而闻名。",
