    taxonomy: { phylum: "被子植物门", class: "木兰纲", order: "豆目", family: "豆科", genus: "黄檀属" },
    summary: "中国海南特有的珍贵用材树种，木材纹理瑰丽、香气独特，是制作古典家具的顶级材料，被列为国家二级保护植物。",
    description: "降香黄檀为落叶乔木，高可达 15 m，树皮灰褐色；奇数羽状复叶，小叶 9–13 枚，卵形至椭圆形。花期 4–6 月，圆锥花序腋生，花淡黄色或白色；荚果长圆形、扁平，成熟时褐色，内含 1–2 粒种子。木材心材红褐色至紫红色，纹理绚丽，有独特香气。\n\n降香黄檀是中国海南特有的珍稀树种，分布于海南岛西部与南部的低山丘陵，喜光、耐旱，适宜砖红壤。木材心材纹理瑰丽、香气独特、耐腐耐磨，是制作古典家具与工艺品的顶级材料，被称为“海南黄花梨”；心材还可入药，中药“降香”能行气活血、止痛。由于长期过度采伐，野生降香黄檀资源濒临枯竭，被列为国家二级保护野生植物。",
