    summary: "桃金娘科常绿小乔木，果实清香多汁、维生素C含量在水果中名列前茅，原产热带美洲，中国华南常见栽培。",
    description: "番石榴为桃金娘科番石榴属常绿小乔木，高 3–10 米，树皮灰褐色、光滑，老枝常呈片状剥落。叶片对生，革质，长椭圆形至卵形，背面被柔毛，揉碎后有特殊气味。花单生或 2–3 朵聚生于叶腋，花瓣白色，雄蕊多数；浆果球形或梨形，成熟时淡黄至粉红，果肉白色、粉红或胭脂红，内含多数坚硬种子。\n\n番石榴原产墨西哥至秘鲁一带的热带美洲，17 世纪由西班牙人传入菲律宾，再经海路传入中国华南，如今广东、广西、福建、台湾、海南等地广泛栽培。它喜高温多湿和充足阳光，耐旱、耐瘠薄，对土壤要求不严，在疏松的沙壤土中结果最好。果实清香多汁，可鲜食、榨汁或制果酱、果脯；维生素C含量约为柑橘的数倍。叶片与果皮在民间入药，有收敛止泻之效。",
