    description: "番木瓜为番木瓜科番木瓜属常绿软木质小乔木，高 3–10 米，茎干粗壮、不分枝，表面有螺旋状排列的叶痕，体内富含白色乳汁。叶片大型，掌状深裂，直径可达 60 厘米，聚生于茎顶，形成伞状树冠。花单性或两性，雄花排成下垂的圆锥花序，雌花单生或数朵簇生；浆果长圆形或球形，成熟时橙黄至橙红，果肉厚实，中央空腔内密布黑褐色种子。\n\n番木瓜原产墨西哥南部至中美洲一带，17 世纪经海路传入中国，现广东、广西、福建、台湾、海南、云南等地广泛栽培。它喜高温多湿和充足阳光，不耐寒，生长期需水量大但忌积水，从播种到结果通常只需一年左右。青果可炖汤、炒食或腌渍，熟果可鲜食、榨汁；未熟果乳汁中的木瓜蛋白酶能分解蛋白质，可用于嫩化肉类，也可提取入药。番木瓜雌雄异株，只有雌株和两性株会结果。",
