    summary: "樟科常绿乔木，果实富含不饱和脂肪酸与多种维生素，口感绵密如黄油，被称为“森林黄油”，原产中美洲。",
    description: "鳄梨为樟科鳄梨属常绿乔木，高 10–20 米，树冠开展，树皮灰褐色并纵裂。叶片互生，革质，椭圆形至卵形，长 10–20 厘米，表面深绿有光泽，背面稍苍白。花小，黄绿色，组成顶生或腋生的圆锥花序；果实为核果，梨形或卵形，长 7–20 厘米，果皮绿色、紫黑色或红褐色，表面粗糙或有光泽，果肉黄绿色、绵软，中央具 1 粒大型种子。\n\n鳄梨原产墨西哥南部至中美洲的高原地区，当地居民食用已有数千年历史，16 世纪传入欧洲，如今墨西哥、秘鲁、智利、美国加利福尼亚是主产区，中国海南、广东、广西、云南、福建等地有引种。它喜温暖湿润、阳光充足和排水良好的环境，不耐霜冻，幼树需适度遮阴。果肉含脂肪约 15%，以油酸等不饱和脂肪酸为主，可鲜食、拌沙拉、制酱或榨油，是近年流行的健康食品；种子与树皮在民间也有药用记载。",
