    summary: "中国原产的落叶小乔木，果实可鲜食、干制成红枣，维生素C含量高，栽培历史可追溯到新石器时代。",
    description: "枣为鼠李科枣属落叶小乔木或灌木状，高可达 10 米，树皮灰褐色、纵裂，小枝呈“之”字形曲折，托叶常变态为坚硬的针刺。叶片互生，卵形至卵状披针形，三出脉明显，表面光滑。花小，黄绿色，簇生于叶腋，具香气，是重要的蜜源；核果长圆形或卵圆形，未熟时青绿，成熟后暗红、表面皱缩，果肉厚实，内含 1 粒坚硬的纺锤形种子。\n\n枣原产中国，黄河中下游一带是栽培中心，考古在河南、河北的新石器时代遗址中发现过枣核，栽培史可追溯到数千年前。它喜光、耐寒、耐旱、耐瘠薄，也耐盐碱，适应性极强，常用分株、嫁接或根插繁殖。鲜枣可生食，干制后即红枣，可煮粥、炖汤、制蜜枣与枣泥；枣花蜜是优质蜂蜜，枣木坚硬可制器具。中国是世界上最主要的枣生产国。",
