    description: "七叶树为七叶树科七叶树属落叶乔木，高 20–25 米，树皮灰褐色、片状剥落，小枝粗壮。掌状复叶对生，小叶 5–7 枚，倒卵状长圆形，边缘具细锯齿，叶柄长。花杂性，白色或淡黄色，组成直立的长圆锥花序，形如烛台，花期 5–6 月；蒴果球形，成熟时黄褐色、3 瓣开裂，内含 1–2 粒栗褐色、有光泽的种子，形似板栗，果期 9–10 月。\n\n七叶树原产中国黄河流域至长江流域，河北、山西、陕西、河南、江苏、浙江等地有分布，多生于山谷杂木林中，北京、杭州等地的寺庙与园林中常见古树。它喜光，稍耐阴，喜凉爽湿润气候与深厚肥沃、排水良好的土壤，生长较慢，寿命长。种子含七叶树素等成分，有毒，不可像栗子那样食用；树皮与种子入药，有散瘀止痛之效。七叶树因叶片形态端庄，常被植于寺院，杭州灵隐寺前的古七叶树颇为有名。",
