    description: "铁力木为藤黄科铁力木属常绿大乔木，高 20–30 米，树皮灰褐色，富含树脂，小枝细长。叶片对生，硬革质，披针形至狭椭圆形，表面深绿有光泽，背面苍白，嫩叶呈粉红色，颇具观赏性。花大，白色至淡粉色，花瓣 4 枚，雄蕊多数，花心金黄，具芳香，花期 3–5 月；果实为蒴果，卵形，成熟时褐色、2–4 瓣开裂，内含 1–4 粒具棱的种子，果期 8–10 月。\n\n铁力木原产印度、缅甸、泰国、越南及中国云南南部、广西南部，生于热带季雨林与河谷林中。它喜高温多湿、阳光充足，适宜深厚肥沃的酸性土壤，生长缓慢。木材极硬重，气干密度可达 1.1 克每立方厘米，入水即沉，耐腐抗虫，是制作高级家具、乐器、雕刻与军工用材的珍稀木材；种子可榨油，树皮与花入药。由于长期过度采伐，野生资源稀少，中国将其列为国家二级保护野生植物。",
