    description: "檀香为檀香科檀香属半寄生常绿小乔木，高 8–12 米，树皮灰褐色、纵裂，小枝细长。叶片对生，革质，卵状披针形，表面淡绿、背面苍白。花小，初开时淡黄绿色，后转紫褐色，组成顶生或腋生的聚伞花序，花期 5–6 月，部分植株可全年零星开花；果实为核果，球形，成熟时紫黑色，内含 1 粒种子，果期 8–9 月。\n\n檀香原产印度南部迈索尔高原及印度尼西亚东部，中国广东、台湾、云南等地有引种。它的根系能与多种植物形成半寄生关系，通过吸器从寄主根部吸收水分与养分，栽培时需配置寄主植物。檀香的心材含檀香油，主要成分为檀香醇，香气持久，是制作香水、香皂、线香与雕刻工艺品的名贵原料，也是中药“檀香”的来源。心材需生长数十年才形成，野生资源因过度采伐而减少，IUCN 将其列为易危物种。",
