    description: "沉香为瑞香科沉香属常绿乔木，高 10–20 米，树皮灰褐色、平滑，小枝细。叶片互生，革质，卵形至椭圆形，表面深绿有光泽。花小，黄绿色，组成腋生或顶生的伞形花序，花期 3–5 月；果实为木质蒴果，扁卵形，成熟时 2 瓣开裂，种子基部具尾状附属物，果期 7–9 月。\n\n沉香原产中国广东、广西、海南、福建、云南等地，也分布于越南、印度尼西亚等东南亚国家，生于海拔 400 米以下的热带、亚热带山地林中。它喜高温多湿和半阴环境，幼树耐阴，适宜疏松肥沃的酸性土壤。沉香树本身并无明显香气，当树干受虫蛀、雷击或人为损伤后，木质部会分泌树脂并逐渐沉积，经数年乃至数十年形成深色芳香的“沉香”。沉香是名贵香料、药材与雕刻材料，中国将其列为国家二级保护野生植物，野生资源已十分稀少。",
