    description: "檀香紫檀为豆科紫檀属落叶乔木，高八至十五米，树皮灰褐色，老树常呈不规则纵裂。奇数羽状复叶，小叶三至五对，阔卵形至近圆形，革质，表面深绿有光泽。花黄色，蝶形花冠，组成腋生或顶生的圆锥花序，花期三至五月；荚果圆形扁平，周围有宽翅，内含种子一至二粒，果期九至十一月。\n\n檀香紫檀原产印度安得拉邦东高止山脉南段，生于干燥的丘陵砾质土壤上，中国广东、广西、海南、云南等地有引种。它极喜光，耐干旱瘠薄，忌积水，生长十分缓慢。心材紫红色至暗红色，纹理细密，密度大而入水即沉，有“十檀九空”之说，是制作高级家具、乐器和工艺雕刻的名贵红木。由于长期过度采伐，野生资源锐减，被 IUCN 列为濒危物种，并列入 CITES 附录Ⅱ。",
