    description: "茶条槭为无患子科槭属落叶小乔木或灌木，高五至六米，树皮灰褐色，小枝细瘦。叶片纸质，卵形或长卵形，常三裂，中裂片较长，边缘具不规则重锯齿，秋季转为鲜红色。花小，黄绿色，组成伞房花序，花期五月；翅果双翅近于水平展开，果期九月。\n\n茶条槭分布于中国东北、华北、内蒙古、陕西、甘肃等地，朝鲜、日本、俄罗斯远东地区也有，多生于海拔八百米以下的山坡、沟谷和河岸。它耐寒、耐旱、耐修剪，对土壤要求不严，在微酸性至中性土壤中均能生长。秋季叶色红艳，是北方重要的观叶树种，也可作绿篱和盆景材料；嫩叶经蒸煮后可代茶饮用，树皮富含纤维，可制绳和造纸。",
