    description: "高山栎为壳斗科栎属常绿乔木，高可达二十米，树皮灰褐色、纵裂，幼枝密被黄褐色绒毛。叶片厚革质，椭圆形至长卵形，边缘具刺状锯齿，表面深绿有光泽，背面被灰黄色绒毛。花单性，雌雄同株，雄花序为下垂的葇荑花序，雌花单生或数朵生于总苞内，花期五至六月；坚果卵形，壳斗杯状、包围果实基部，果期翌年九至十月。\n\n高山栎分布于中国西藏、云南西北部以及尼泊尔、印度、不丹等地，多生于海拔两千至四千米的高山地带，常形成纯林或与针叶树混生。它耐寒、抗风、耐瘠薄，适宜排水良好的山地棕壤，是喜马拉雅山区重要的水源涵养林树种。木材坚硬耐腐，可供建筑和薪炭用材；树叶可饲养柞蚕，坚果可提取淀粉。高山栎林对维持高原生态平衡具有重要作用。",
