    description: "榔榆为榆科榆属落叶乔木，高可达二十五米，树皮灰褐色、成不规则鳞片状剥落，剥落后露出红褐色内皮。叶片互生，革质，椭圆形至卵状披针形，较小，边缘具单锯齿，表面深绿有光泽。花簇生于叶腋，两性，花期八至九月；翅果椭圆形，种子位于翅果中央，成熟时黄褐色，果期十月。\n\n榔榆分布于中国华北、华东、华中、华南及西南各地，日本、朝鲜半岛也有，多生于平原、丘陵和溪边。它喜光、耐旱、耐瘠薄，对土壤要求不严，在酸性、中性至微碱性土壤中均能生长，抗风力强。木材坚韧，可供家具、农具和车辆用材；树皮纤维可制绳和造纸；树姿古朴、萌芽力强，是制作树桩盆景的优良材料，也常作行道树和护岸树。",
