    description: "青檀为大麻科青檀属落叶乔木，高可达二十米，树皮灰白色、呈长片状剥落，露出灰绿色内皮。叶片互生，卵形至椭圆状卵形，边缘具锐锯齿，基部三出脉，表面粗糙。花单性，雌雄同株，雄花簇生于叶腋，雌花单生，花期四月；坚果具木质翅，近圆形，成熟时黄褐色，果期八至九月。\n\n青檀是中国特有的单型属植物，分布于河北、山西、陕西、甘肃、四川、贵州、湖北、湖南、江西、安徽、江苏、浙江等地，多生于石灰岩山地和溪谷。它喜光、耐干旱瘠薄，适宜石灰质土壤，在岩石缝隙中也能生长。树皮纤维细长、韧性好，是制作宣纸的主要原料，安徽泾县的宣纸即以青檀皮为原料；木材坚硬，可制农具和家具。由于野生资源减少，被列为国家二级重点保护野生植物。",
