    description: "南酸枣为漆树科南酸枣属落叶乔木，高可达二十米，树皮灰褐色、纵裂，树冠宽广。奇数羽状复叶，小叶七至十五片，卵状披针形，全缘，表面深绿。花杂性，雌雄同株，组成圆锥花序，花小，淡紫色，花期四月；核果椭圆形，成熟时橙黄色，果肉黏滑，果核坚硬、顶端有五个小孔，果期八至十月。\n\n南酸枣分布于中国广东、广西、福建、浙江、江西、湖南、湖北、四川、贵州、云南等地，印度、尼泊尔、中南半岛也有，多生于海拔一千米以下的沟谷和山坡疏林中。它喜温暖湿润和充足阳光，适宜深厚肥沃、排水良好的土壤，生长迅速。果肉酸甜可食，可制果酱和饮料；果核可作活性炭，五个小孔使其常被串成五眼六通念珠；树皮可提取栲胶。南酸枣是南方重要的乡土果树和绿化树种。",
