    summary: "山龙眼科银桦属常绿乔木，羽状深裂的叶片背面密被银白色绢毛，盛花时满树橙黄，是南方常见的行道树。",
    description: "银桦为山龙眼科银桦属常绿乔木，高二十至四十米，树皮灰褐色、粗糙纵裂，树冠圆锥形。叶片羽状深裂，裂片狭长，表面深绿色，背面密被银白色绢毛，随风翻动时银光闪闪。花橙黄色，花被片向外卷曲，组成总状花序，形似牙刷，花期五月；蓇葖果木质，成熟时开裂，种子具翅，果期八至十月。\n\n银桦原产澳大利亚东部，中国广东、广西、福建、云南、台湾等地有引种，多作行道树和庭园树栽培。它喜光和温暖湿润的气候，不耐寒，适宜深厚肥沃、排水良好的酸性土壤，根系发达。树形高大通直、叶背银白，是优良的行道树和风景树；木材淡红色、纹理直，可制家具和胶合板；花富含花蜜，是优良的蜜源植物。银桦在华南城市绿化中应用广泛。",
    habitat: "热带亚热带低山丘陵，喜光喜湿、不耐寒，适宜酸性土",
