    description: "伯乐树为叠珠树科伯乐树属落叶乔木，高十至二十米，树皮灰白色、平滑，小枝粗壮。奇数羽状复叶，小叶七至十五片，长卵形至倒卵形，边缘全缘，表面深绿。花大，粉红色，组成顶生的总状花序，花萼钟状，花瓣五枚，花期四至五月；蒴果木质，近球形，成熟时红褐色并三瓣开裂，果期九至十月。\n\n伯乐树是中国特有的单型科植物，分布于江西、湖南、广东、广西、云南、贵州、浙江、福建、四川等地，多生于海拔五百至一千七百米的山谷、溪边和常绿阔叶林中。它喜温暖湿润和半阴环境，适宜土层深厚、排水良好的酸性黄壤。花大色艳，可作庭园观赏树；木材纹理直，可制器具。由于分布零散、天然更新困难，野生植株数量稀少，被列为国家一级重点保护野生植物。",
