    description: "银杉为松科银杉属常绿乔木，高可达二十米，树干通直，树皮暗灰色、呈不规则薄片剥落。叶条形，螺旋状排列，长四至六厘米，表面深绿色，背面有两条银白色的气孔带，远望如银线。雌雄同株，雄球花黄色，雌球花绿色，花期五月；球果卵圆形，成熟时淡褐色，果期翌年十月。\n\n银杉是中国特有的孑遗植物，分布于广西龙胜、四川金佛山、湖南新宁、贵州道真等地，多生于海拔七百至一千八百米的石灰岩山地和山脊。它喜温暖湿润、云雾缭绕的环境，耐寒、耐瘠薄，适宜石灰质土壤，生长缓慢。银杉对研究松科植物的系统发育和古气候具有重要意义，被称为植物活化石；树姿优美，可作观赏树。由于分布区狭窄、繁殖困难，被列为国家一级重点保护野生植物。",
