    description: "墨西哥落羽杉为常绿或半常绿大乔木，高可达 30–40 米，主干粗壮通直，树皮灰褐色并纵裂成条片。叶片条形、扁平，在侧枝上排成整齐两列，幼树叶片柔软，老树较硬。雌雄同株，雄球花生于小枝顶端，雌球花单生，球果近球形，成熟时深褐色，种子具翅，可随风传播。\n\n该种原产墨西哥与危地马拉的高原河谷、溪流两岸，常沿水系形成纯林，是墨西哥的国树，传说阿兹特克末代君主曾在树下哭泣，因而有“悲伤之夜之树”的别称。它喜充足光照与湿润土壤，耐水湿，可长期生于浅水中，但幼期不耐霜冻。木材轻软，可制家具、箱板与造纸；树姿雄伟，适合在温暖地区作滨水景观树。中国南方植物园与湿地公园已有引种栽培。",
