    description: "观光木为常绿乔木，高可达 25 米，树皮灰褐色并具纵裂纹，小枝、芽与叶柄均被黄褐色柔毛。叶片倒卵状椭圆形，长 8–17 厘米，上面深绿色，下面被锈色柔毛。花单生叶腋，淡黄色，芳香浓郁，花被片 9–10 枚，雄蕊群与雌蕊群均显著。聚合果长椭圆形，长 10–12 厘米，成熟时开裂，露出红色种子。\n\n本种为中国特有种，分布于广东、广西、福建、江西、湖南、云南、贵州与海南等地，生于海拔 500–1000 米的山地常绿阔叶林中，喜温暖湿润、多云雾的环境与肥沃排水良好的酸性土壤。它树形整齐、花香浓郁，是优良的园林观赏树；木材轻软细致，可供家具与建筑。因天然林被采伐、野生种群零星，观光木被列为国家二级保护野生植物，各地已开展人工育苗与迁地保护。",
