    description: "天目木兰为落叶乔木，高可达 12 米，树皮灰白色、平滑，小枝细长。叶片倒卵形或椭圆状倒卵形，长 10–15 厘米，先端渐尖，下面被白色短柔毛。花先叶开放，单生枝顶，花被片 9 枚，淡粉红色至紫红色，芳香，直径约 8 厘米；聚合果圆柱形，长 10–15 厘米，成熟时开裂露出红色种子。\n\n本种为中国特有种，野生植株仅见于浙江天目山、安徽黄山与江西、江苏部分山地，生于海拔 700–1000 米的常绿阔叶林与灌丛中，喜凉爽湿润、多云雾的山地气候与肥沃的酸性土壤。它花大色艳、先花后叶，是优良的早春观赏树种，各地植物园已有引种栽培。由于分布区狭窄、野生个体稀少，天目木兰被列为国家二级保护野生植物，IUCN 评估为易危。",
