    description: "紫玉兰为落叶灌木或小乔木，高可达 3–4 米，常丛生，树皮灰褐色，小枝紫褐色。叶片椭圆状倒卵形，长 8–18 厘米，先端渐尖，上面深绿色，下面沿脉有短柔毛。花先叶开放或与叶同放，单生枝顶，花被片 9 枚，外轮 3 枚较小、紫绿色，内两轮紫红色、内面白色，花大而艳丽；聚合果圆柱形，成熟时开裂露出红色种子。\n\n紫玉兰原产中国中部，四川、云南、湖北等地有野生分布，现全国及世界各地广泛栽培，栽培历史可追溯至唐代。它喜光、喜温暖湿润气候与肥沃排水良好的微酸性土壤，耐寒性较强，是早春重要的观花树种。其花蕾入药称“辛夷”，可散风寒、通鼻窍，是治疗鼻炎的传统药材。紫玉兰也是二乔玉兰等杂交品种的重要亲本之一，在园林中常与白玉兰、二乔玉兰搭配种植。",
