    description: "滇润楠为常绿乔木，高可达 30 米，树皮灰褐色，小枝绿色或黄褐色。叶片革质，倒卵形至椭圆形，长 8–15 厘米，上面深绿色有光泽，下面苍白色，羽状脉明显。圆锥花序生于枝顶或叶腋，花小、黄绿色；浆果状核果球形，成熟时紫黑色，果托杯状。\n\n本种为中国特有种，分布于云南、四川西南部与西藏东南部，生于海拔 1500–2500 米的山地常绿阔叶林中，喜温暖湿润、多云雾的气候与深厚肥沃的酸性土壤。它是滇中高原重要的用材与园林树种，木材纹理直、结构细、耐腐，可供建筑、家具与雕刻；树冠浓密，也常作行道树与风景树。野生资源因长期采伐而下降，需加强保护与人工更新。",
